"""Content and exact footer paths derived from the supplied AutoZoWeg HTML."""
from html import escape

FOOTER_GROUPS = {
 'Belangrijk': [('auto-verkopen','Bus verkopen'),('hoe-werkt-het','Hoe werkt het?'),('aanmelden','Bus aanmelden'),('advies','Advies'),('contact','Contact'),('dealer-portal/registreren','Dealer worden'),('sitemap','Sitemap')],
 'Verder lezen': [('auto-verkopen-vergelijken','Verkoopplatforms vergelijken'),('auto-verkopen-per-merk','Per merk en model'),('auto-verkopen-problemen','Verkopen met problemen'),('auto-verkopen-situaties','Bijzondere situaties'),('auto-verkopen-beslissingen','Beste verkooproute'),('over-ons','Over VerkoopJouwBus')],
 'Per merk': [('volkswagen-verkopen','Volkswagen verkopen'),('opel-verkopen','Opel verkopen'),('renault-verkopen','Renault verkopen'),('ford-verkopen','Ford verkopen'),('toyota-verkopen','Toyota verkopen'),('mercedes-verkopen','Mercedes-Benz verkopen')],
 'Per stad': [('auto-verkopen-'+s,'Bus verkopen '+n) for s,n in [('amsterdam','Amsterdam'),('rotterdam','Rotterdam'),('den-haag','Den Haag'),('utrecht','Utrecht'),('eindhoven','Eindhoven'),('tilburg','Tilburg'),('groningen','Groningen'),('breda','Breda')]],
 'Bijzondere situaties': [('auto-zonder-apk-verkopen','Bus zonder APK'),('schadeauto-verkopen','Bus met schade'),('auto-met-hoge-kilometerstand-verkopen','Hoge kilometerstand'),('bedrijfsauto-verkopen','Bedrijfswagen verkopen'),('bestelbus-verkopen','Bestelbus verkopen')],
 'Rekentools & data': [('auto-schorsen-berekenen','Schorsen of verkopen?'),('auto-repareren-of-verkopen','Repareren of verkopen?'),('particulier-of-opkoper-berekenen','Particulier of inkoper?'),('apk-check','APK-check'),('apk-cijfers','APK-cijfers per model'),('terugroepacties','Terugroepacties'),('welke-auto-gaat-het-langst-mee','Levensduur van een bus'),('hoeveel-elektrische-autos-in-nederland','Elektrische voertuigen'),('auto-export-cijfers','Export in cijfers'),('wagenpark-per-provincie','Wagenpark per provincie'),('wagenpark-per-gemeente','Wagenpark per gemeente'),('tellerfraude','Tellerstand en tellerfraude')],
 'Meer informatie': [('privacy','Privacybeleid'),('voorwaarden','Algemene voorwaarden'),('werken-bij','Werken bij ons'),('pers','Pers & data')],
}

def cards(items):
 return '<div class="route-list">'+''.join(f'<a href="/{p}/">{escape(n)} <span aria-hidden="true">↗</span></a>' for p,n in items)+'</div>'

def paragraphs(items):
 return ''.join(f'<h2>{escape(h)}</h2><p>{escape(p)}</p>' for h,p in items)

def calculator(kind):
 fields={
 'repair':[('na','Geschatte verkoopprijs na reparatie (€)',8000),('nu','Aanbod in huidige staat (€)',5500),('kosten','Totale reparatiekosten (€)',1500),('extra','Extra kosten / risicobuffer (€)',300)],
 'suspend':[('maanden','Aantal maanden stalling',6),('vast','Vaste kosten per maand zonder schorsing (€)',180),('stalling','Stallingskosten per maand (€)',45),('schorsing','Kosten schorsing (€)',90),('waardedaling','Geschatte waardedaling per maand (€)',100)],
 'private':[('particulier','Geschatte particuliere verkoopprijs (€)',9000),('inkoper','Concreet aanbod inkoper (€)',8000),('advertentie','Advertentie- en voorbereidingskosten (€)',150),('uren','Geschatte tijdsbesteding (uren)',12),('uurwaarde','Eigen waarde per uur (€)',40),('risico','Kosten- en risicobuffer (€)',250)],
 'depreciation':[('prijs','Oorspronkelijke prijs (€)',30000),('rest','Geschatte huidige waarde (€)',15000),('jaren','Aantal jaren',5)],
 }
 return '<form class="calculator" data-calculator="'+kind+'"><div class="form-grid">'+''.join(f'<label>{escape(label)}<input name="{key}" type="number" min="{1 if key == "jaren" else 0}" max="10000000" step="any" required value="{value}"></label>' for key,label,value in fields[kind])+'</div><button class="btn" type="submit" style="margin-top:20px">Bereken mijn scenario</button><output class="calculation-result" aria-live="polite"></output><p class="form-note">Indicatieve vergelijking op basis van je eigen invoer; geen taxatie of financieel advies. Gebruik vergelijkbare bedragen inclusief of exclusief btw.</p></form>'

def rdw():
 return '''<form class="rdw-check"><label for="rdw-plate">Nederlands kenteken<input class="plate" id="rdw-plate" name="rdw-kenteken" maxlength="12" placeholder="AB-123-C" required></label><button class="btn" type="submit" style="margin-top:15px">Bekijk voertuiggegevens</button><div class="rdw-result" role="status" aria-live="polite"></div><p class="form-note">Bron: openbare voertuiggegevens van RDW. Beschikbaarheid en volledigheid verschillen per voertuig. Geen automatische taxatie of voorspelling.</p></form>'''

def content_pages(services, brands, form, faq_block):
 result=[]
 def add(path,title,description,html,noindex=False):result.append((path,title,description,html,noindex))
 aliases={'auto-verkopen':'bus-verkopen','bedrijfsauto-verkopen':'bedrijfswagen-verkopen','auto-zonder-apk-verkopen':'bus-zonder-apk-verkopen','schadeauto-verkopen':'bus-met-schade-verkopen','auto-met-hoge-kilometerstand-verkopen':'bus-met-hoge-kilometerstand'}
 for path,target in aliases.items():
  title,heading,desc,parts=services[target]
  add(path,title,desc,paragraphs(parts)+'<p><a href="/'+target+'/">Meer informatie over '+escape(title.lower())+' →</a></p>')
 for path,name in FOOTER_GROUPS['Per merk']:
  slug={'mercedes':'mercedes-benz'}.get(path.removesuffix('-verkopen'),path.removesuffix('-verkopen'))
  if slug in brands:
   brand,models,advice=brands[slug]
  else:brand,models,advice='Toyota','Proace, Proace City en Hiace','Vermeld de precieze modelnaam, uitvoering en leeftijd. De Proace City en Proace hebben andere laadruimtes; bij een Hiace kan de oudere onderhoudshistorie extra belangrijk zijn. Bij elektrische modellen zijn accu- en laadgegevens relevant.'
  add(path,brand+' bus verkopen','Je '+brand+' bedrijfswagen verkopen: model, uitvoering, onderhoud en aanvraag.',paragraphs([(models,advice),('Welke documenten helpen?','Houd onderhoudsfacturen en voertuiggegevens klaar. Deel foto’s van de cabine, laadruimte en buitenkant. Benoem aanwezige accessoires en bekende schade. Als de bus is gefinancierd, controleer dan eerst de voorwaarden bij de financier.'),('Van aanvraag naar besluit','Een aanvraag is geen verkoopverplichting. Een concreet aanbod moet duidelijk maken hoe inspectie, betaling, transport en overschrijving verlopen. Vergelijk aanbiedingen op dezelfde basis en controleer of de prijs inclusief of exclusief btw is.')]))
 city_details={
 'Amsterdam':('toegang tot de stad','Controleer de actuele regels voor milieuzones en zero-emissiezones bij de gemeente Amsterdam. Die kunnen invloed hebben op hoe je de bus nog gebruikt. Vermeld je voertuigcategorie en emissieklasse; leid toelating niet alleen af uit het bouwjaar.'),
 'Rotterdam':('laadplek en transport','Maak vooraf afspraken over de plek voor inspectie en overdracht. Een bedrijfsbus op een druk bedrijventerrein, in een garage of bij een laadplaats vraagt een andere voorbereiding. Controleer ook de gemeentelijke toegangsregels.'),
 'Den Haag':('parkeren en bereikbaarheid','Geef bij een afspraak aan of de bus op eigen terrein of op straat staat. Controleer parkeer- en toegangsvoorwaarden voordat je een inspectie of transport afspreekt. Meld het als de bus niet veilig kan rijden.'),
 'Utrecht':('milieuzones en gebruik','Controleer bij de gemeente de actuele regels voor de zones waar je werkt. De registratie en emissieklasse zijn belangrijker dan een algemene aanname over dieselbussen. Vermeld ook hoeveel van je ritten in de stad plaatsvinden.'),
 'Eindhoven':('werkbus en inrichting','Beschrijf de inrichting van je bus, bijvoorbeeld gereedschapsrekken of een laadklep. Bepaal welke spullen je vóór overdracht verwijdert. Vergelijk aanbiedingen inclusief eventuele transportkosten en btw.'),
 'Tilburg':('logistiek en overdracht','Plan inspectie en transport op een plek waar een bus veilig kan worden bekeken of geladen. Vermeld lengte, hoogte en bereikbaarheid. Laat weten als toegang tot je terrein een afspraak of aanmelding vereist.'),
 'Groningen':('afstand en afspraak','Bespreek vooraf hoe inspectie en eventuele ophaling worden georganiseerd. Maak geen aanname over gratis transport; controleer de afspraken in het aanbod. Meld of de bus rijdbaar is en of de APK nog geldig is.'),
 'Breda':('prijs en zakelijke verkoop','Bij een zakelijke verkoop moeten prijs en btw-status duidelijk zijn. Houd factuurgegevens en onderhoud klaar. Controleer lopende financiering en bespreek de verkoop met je boekhouder als je twijfelt over de administratie.'),
 }
 for path,label in FOOTER_GROUPS['Per stad']:
  city=label.removeprefix('Bus verkopen ');subject,advice=city_details[city]
  add(path,'Bus verkopen in '+city,'Je bedrijfsbus verkopen in '+city+': voorbereiding, '+subject+' en een vrijblijvende aanvraag.',paragraphs([('Aandacht voor '+subject,advice),('Wat geef je door?','Deel het kenteken, de actuele kilometerstand, uitvoering en bekende gebreken. Geef je woonplaats of de locatie van de bus door in de toelichting, zodat bereikbaarheid en eventuele transportafspraken kunnen worden besproken.'),('Heldere afspraken, waar je bus ook staat','Vraag wie de koper is, of een inspectie plaatsvindt en hoe eventuele prijswijzigingen worden afgesproken. Controleer bij overdracht de betaling en het vrijwaringsbewijs. VerkoopJouwBus vermeldt op deze pagina geen lokale vestiging of plaatselijk kantoor.')]))
 add('hoe-werkt-het','Hoe werkt VerkoopJouwBus?','Van voertuiggegevens tot aanbod en overdracht: zo bereid je een busverkoop voor.',paragraphs([('1. Deel de voertuiggegevens','Begin met kenteken, kilometerstand en een beschrijving van je bus. Je kunt de openbare RDW-gegevens bekijken, maar controleer zelf altijd de uitvoering en staat.'),('2. Bespreek een concreet aanbod','Een aanvraag is vrijblijvend. Voor een beoordeling kunnen extra foto’s of documenten nodig zijn. Controleer prijs, btw-status en voorwaarden voordat je akkoord gaat.'),('3. Controleer de overdracht','Leg afspraken over inspectie, transport en betaling vast. Zorg voor de juiste kentekendocumenten en controleer dat je een vrijwaringsbewijs ontvangt voordat je de bus meegeeft.')]))
 add('aanmelden','Meld je bedrijfsbus aan','Vrijblijvend contact aanvragen over je bestelbus of bedrijfswagen.',rdw()+'<p><a class="btn" href="/#aanvragen">Verder met mijn aanvraag</a></p>')
 add('auto-verkopen-per-merk','Verkopen per merk en model','Bekijk de voorbereiding voor Volkswagen, Ford, Mercedes-Benz, Toyota en andere merken.',cards(FOOTER_GROUPS['Per merk'])+cards([('merken/'+k,v[0]) for k,v in brands.items()]))
 add('auto-verkopen-problemen','Bus verkopen met problemen','Informatie over schade, verlopen APK en een hoge kilometerstand.',paragraphs([('Maak het probleem concreet','Omschrijf het defect en wat je al hebt laten onderzoeken. Vermeld storingslampjes, reparatieoffertes en of de bus kan rijden. Een koper kan alleen zorgvuldig beoordelen als de informatie volledig is.')])+cards(FOOTER_GROUPS['Bijzondere situaties']))
 add('auto-verkopen-situaties','Verkopen in bijzondere situaties','Bereid verkoop voor bij lease, bedrijfsbeëindiging, erfenis of schade.',paragraphs([('Bedrijfsbeëindiging','Controleer wie eigenaar is, of er financiering loopt en hoe de btw moet worden verwerkt. Een uitschrijving van je onderneming regelt de verkoop van een voertuig niet automatisch.'),('Lease of financiering','Lees de overeenkomst en vraag de financier om de mogelijkheden. Een gebruiker kan niet zonder meer een voertuig van de leasemaatschappij verkopen.'),('Erfenis of verkoop namens iemand anders','Zorg dat duidelijk is wie bevoegd is tot verkoop. Raadpleeg de RDW over tenaamstelling en benodigde documenten. Deel geen identiteitsdocumenten via een openbaar aanvraagformulier.'),('Schade of een verlopen APK','Breng de staat in beeld en controleer transportvoorwaarden. Rijd niet met een onveilige bus naar een afspraak.')]))
 comparison=paragraphs([('Particulier verkopen','Je bepaalt zelf je vraagprijs en hebt contact met geïnteresseerden. Houd rekening met advertenties, proefritten, tijd, onderhandelingen en veilig betalingsverkeer.'),('Verkopen aan een inkoper','Een concreet inkoopbod geeft vaak eerder duidelijkheid over de prijs. Controleer de voorwaarden, inspectie, betaling en eventuele transportkosten. Een snelle procedure zegt op zichzelf niets over het beste bod.'),('Inruilen','Inruil kan praktisch zijn als je een ander voertuig koopt. Vergelijk de combinatie van aankoopprijs en inruilwaarde, en kijk ook naar een losse verkoop.'),('Vergelijk op dezelfde basis','Zet prijzen inclusief of exclusief btw naast elkaar. Neem kosten, tijd en eventuele wijzigingen na inspectie mee. Ga niet alleen af op een indicatie die geen bindend aanbod is.')])
 add('auto-verkopen-vergelijken','Verkooproutes vergelijken','Vergelijk particuliere verkoop, een inkoper en inruil op kosten, tijd en voorwaarden.',comparison+cards([('particulier-of-opkoper-berekenen','Vergelijk je eigen scenario')]))
 add('auto-verkopen-beslissingen','Welke verkooproute past bij je?','Een verkooproute kiezen op basis van jouw prioriteiten, beschikbare tijd en concrete aanbiedingen.',paragraphs([('Hoeveel tijd heb je?','Als je tijd hebt voor advertenties en afspraken, kan particuliere verkoop passen. Heb je behoefte aan sneller overzicht, vergelijk dan concrete aanbiedingen van inkopers. Controleer ook of je de bus nog nodig hebt.'),('Hoe zeker moet de prijs zijn?','Een vraagprijs is geen opbrengst en een online indicatie is geen definitief bod. Vraag welke omstandigheden de prijs nog kunnen veranderen, zoals inspectie of niet gemelde schade.'),('Wat zijn de totale kosten?','Neem advertenties, stalling, verzekering, reparaties en eventuele transportkosten mee. Gebruik de rekentools als scenariovergelijking en vervang de voorbeeldbedragen door je eigen informatie.')])+cards(FOOTER_GROUPS['Rekentools & data'][:3]))
 add('advies','Advies over je bus verkopen','Praktische informatie over waarde, verkooproutes, APK, tellerstand en overdracht.',cards(FOOTER_GROUPS['Verder lezen'])+cards([('wat-is-mijn-auto-waard','Wat is mijn bus waard?'),('afschrijving-auto','Afschrijving berekenen'),('advies/waarde/wat-bepaalt-de-waarde-van-mijn-auto','Wat bepaalt de waarde?')])+cards(FOOTER_GROUPS['Rekentools & data']))
 value=paragraphs([('Een indicatie is geen inkoopbod','Een geschatte marktwaarde verschilt van het bedrag dat een koper onder concrete voorwaarden wil betalen. Vergelijk daarom niet alleen getallen maar ook inspectie, transport en betaling.'),('Bouwjaar, uitvoering en kilometerstand','Vergelijk voertuigen met dezelfde carrosserie, aandrijving en uitvoering. Een lange hoge bestelbus is niet rechtstreeks vergelijkbaar met een korte lage uitvoering. Kilometerstand krijgt betekenis in combinatie met onderhoud en gebruik.'),('Onderhoud, APK en schade','Een aantoonbare onderhoudshistorie maakt de staat beter te beoordelen. Een geldige APK is geen volledige technische garantie. Schade en verwachte reparaties kunnen de afweging van een koper veranderen.'),('Vraag en inzetbaarheid','Laadvermogen, brandstof, inrichting en actuele toegangsregels beïnvloeden voor wie een bus bruikbaar is. Onderzoek dit voor jouw voertuig in plaats van een algemeen percentage te gebruiken.')])
 add('wat-is-mijn-auto-waard','Wat is mijn bus waard?','Wat bouwjaar, uitvoering, onderhoud en vraag betekenen voor de beoordeling van een bus.',value)
 add('advies/waarde/wat-bepaalt-de-waarde-van-mijn-auto','Wat bepaalt de waarde van je bus?','De waarde van een bedrijfswagen: uitvoering, gebruik, onderhoud en een concreet aanbod.',value+cards([('afschrijving-auto','Bereken afschrijving met je eigen waardeschatting')]))
 for path,title,kind,intro in [
  ('auto-repareren-of-verkopen','Repareren of verkopen?','repair','Vergelijk de geschatte opbrengst na reparatie met een concreet bod in huidige staat. Het verschil na aftrek van reparatie en risicobuffer is het saldo van dit scenario; andere kosten kunnen nog meetellen.'),
  ('auto-schorsen-berekenen','Schorsen of verkopen?','suspend','Vergelijk je geschatte kosten van aanhouden met en zonder schorsing. De vergelijking is geen voorspelling van verkoopopbrengst. Tijdens schorsing gelden voorwaarden voor gebruik en stalling; controleer die bij de RDW.'),
  ('particulier-of-opkoper-berekenen','Particulier of inkoper?','private','Vergelijk een particuliere opbrengst na kosten, tijd en buffer met een concreet inkoopbod. De waarde van je eigen tijd is een persoonlijke aanname, geen factuur.'),
  ('afschrijving-auto','Afschrijving berekenen','depreciation','Bereken het verschil tussen aankoopprijs en je eigen geschatte huidige waarde. De uitkomst toont totale afschrijving en een gemiddelde per jaar; het is geen taxatie en geen lineaire voorspelling voor toekomstige jaren.')]:
  add(path,title,intro, '<p>'+escape(intro)+'</p>'+calculator(kind)+paragraphs([('Gebruik controleerbare bedragen','Vervang voorbeeldbedragen door je eigen kosten, offertes en concrete aanbiedingen. Vergelijk btw-bedragen op dezelfde basis. Maak ook een minder gunstig scenario als bedragen nog onzeker zijn.'),('Beslis niet alleen op het saldo','Transport, contractvoorwaarden, financiering en hoe lang je de bus nog nodig hebt kunnen doorslaggevend zijn. Een rekensom neemt die beslissing niet over.')]))
 add('apk-check','APK en kenteken controleren','Bekijk de openbare APK-vervaldatum van een Nederlands voertuig via RDW.',rdw()+paragraphs([('Geen afkeurkans-voorspelling','Een APK-vervaldatum zegt niet hoe groot de kans op afkeur is. Deze site berekent geen afkeurkans op basis van merk of bouwjaar. Laat de actuele technische staat beoordelen door een keuringsbedrijf.'),('Controleer de registratie','De koppeling toont openbare RDW-velden als deze beschikbaar zijn. Controleer onverwachte of ontbrekende gegevens rechtstreeks bij de RDW. Een geïmporteerd of geschorst voertuig kan aanvullende aandacht vragen.')]))
 add('tellerfraude','Tellerstand en tellerfraude','Wat een tellerstandoordeel betekent en hoe je een kilometerhistorie controleert.',rdw()+paragraphs([('Logisch, onlogisch of geen oordeel','Een tellerstandoordeel is geen garantie dat een voertuig nooit is gemanipuleerd. Bekijk de actuele toelichting van de RDW en controleer ook facturen en onderhoudsregistraties.'),('Een onduidelijke historie','Vraag naar vervangen tellers, importhistorie en ontbrekende documenten. Vermeld twijfel bij verkoop; presenteer een onzekere stand niet als een sluitende historie.'),('Geen verzonnen statistiek','Deze pagina toont geen fraudepercentage zonder een verifieerbare dataset, meetperiode en methode. De kentekencheck gebruikt alleen beschikbare openbare voertuiggegevens.')]))
 add('terugroepacties','Terugroepacties controleren','Controleer bij RDW en de fabrikant of een voertuig een openstaande terugroepactie heeft.',paragraphs([('Controleer RDW en fabrikant','Gebruik het officiële terugroepregister en vraag een merkdealer of er op het chassisnummer nog acties openstaan. Niet iedere actie is op dezelfde manier in een algemene voertuigregistratie zichtbaar.'),('Laat uitvoering bevestigen','Een melding dat een type onder een actie valt, bewijst niet dat de reparatie aan jouw bus al is uitgevoerd. Vraag om een bevestiging of factuur en bewaar die bij de onderhoudshistorie.'),('Belangrijk bij verkoop','Geef bekende openstaande acties door. Informeer ook of er beperkingen gelden voor veilig gebruik. Deze website geeft geen automatische vrijgave om met een voertuig te rijden.')])+'<p><a class="btn" href="https://www.rdw.nl/" target="_blank" rel="noopener noreferrer">Naar RDW</a></p>')
 datasets={
 'apk-cijfers':('APK-cijfers per model','Vergelijk APK-cijfers alleen met een heldere meetperiode en methode.','Een model met oudere voertuigen is niet direct vergelijkbaar met een jonger wagenpark. Kilometerstand, gebruik en selectie van keuringen kunnen resultaten beïnvloeden. Een percentage per model voorspelt niet de uitkomst van jouw keuring.'),
 'welke-auto-gaat-het-langst-mee':('Welke bus gaat het langst mee?','Onderhoud en inzet bepalen mede de levensduur van een bedrijfsbus.','De leeftijd van nog geregistreerde voertuigen bewijst geen gemiddelde levensduur. Uitgevallen voertuigen kunnen uit een analyse verdwijnen. Vergelijk motor, uitvoering, onderhoud en inzet voordat je een model als duurzamer bestempelt.'),
 'hoeveel-elektrische-autos-in-nederland':('Elektrische voertuigen in Nederland','Waar je op let bij cijfers over elektrische voertuigen.','Maak onderscheid tussen volledig elektrische voertuigen en plug-inhybrides. Kies of je personenauto’s, bestelwagens of alle voertuigcategorieën telt. Noteer de peildatum en tel niet ongemerkt een voertuig in meerdere groepen.'),
 'auto-export-cijfers':('Voertuigexport in cijfers','Exportdata begrijpen en een zakelijke verkoop voorbereiden.','Een exportregistratie is niet hetzelfde als de verkoopprijs of uiteindelijke bestemming. Noteer periode en voertuigcategorie. Voor een daadwerkelijke export zijn aparte procedures en documenten nodig; raadpleeg de RDW.'),
 'wagenpark-per-provincie':('Wagenpark per provincie','Regionale voertuigcijfers in hun context bekijken.','Een registratieadres vertelt niet waar een bus meestal rijdt. Leasemaatschappijen en grote wagenparken kunnen regionale cijfers beïnvloeden. Vergelijk absolute aantallen en aantallen per inwoner niet zonder onderscheid.'),
 'wagenpark-per-gemeente':('Wagenpark per gemeente','Let op definities bij gemeentelijke cijfers en EV-aandelen.','Gemeentegrenzen en codes kunnen wijzigen. Leg vast welke indeling en peildatum je gebruikt. Bij een EV-aandeel moet duidelijk zijn of de noemer alle voertuigen, personenauto’s of alleen bedrijfswagens bevat.'),
 }
 for path,(title,description,advice) in datasets.items():
  add(path,title,description,paragraphs([('Zo lees je de cijfers',advice),('Bron en actualiteit','Gebruik officiële bronnen zoals RDW Open Data en CBS StatLine. Noteer dataset, selectie, peildatum en eventuele uitsluitingen. Een verschil tussen bronnen kan uit een andere definitie komen.'),('Geen ongecontroleerde cijfers','Voor deze versie is geen volledige statistische dataset ingelezen of gevalideerd. Daarom worden geen aantallen, rankings of voorspellingen getoond. De onderstaande bronlinks zijn bedoeld om actuele publicaties te raadplegen.')])+'<div class="route-list"><a href="https://opendata.rdw.nl/" target="_blank" rel="noopener noreferrer">RDW Open Data ↗</a><a href="https://opendata.cbs.nl/statline/" target="_blank" rel="noopener noreferrer">CBS StatLine ↗</a></div>')
 add('over-ons','Over VerkoopJouwBus','VerkoopJouwBus is gericht op aanvragen voor bestelbussen en bedrijfswagens.',paragraphs([('Een duidelijke start','Deze website bundelt praktische uitleg over bedrijfsbussen, verkooproutes en overdracht. Via het aanvraagformulier kun je contact vragen over jouw voertuig.'),('Persoonlijk contact','Bel 085-130-1900 of mail info@verkoopjouwbus.nl met vragen over de aanvraag. Deel geen volledige tenaamstellingscode of identiteitsdocument via e-mail of het formulier.'),('Jij beslist','Het insturen van voertuiggegevens is geen verkoopovereenkomst. Een concreet aanbod en afspraken over inspectie, transport en betaling moeten afzonderlijk worden besproken.')]))
 add('voorwaarden','Algemene voorwaarden','Conceptvoorwaarden voor aanvragen via VerkoopJouwBus.','<div class="notice">Concept: juridische bedrijfsnaam, adres, KvK-gegevens en definitieve voorwaarden moeten vóór livegebruik worden ingevuld en gecontroleerd.</div>'+paragraphs([('Aanvraag en overeenkomst','Het formulier is een verzoek om contact. Een verkoopovereenkomst ontstaat niet door het invullen van een kenteken of versturen van een aanvraag.'),('Informatie over het voertuig','Geef gegevens zo volledig en correct mogelijk door. Meld bekende gebreken en vermeld of er financiering of lease loopt.'),('Aanbod en overdracht','Prijs, eventuele inspectie, transport, betaling en overschrijving horen in concrete afspraken te worden vastgelegd. Deze website legt die voorwaarden niet automatisch vast.'),('Rekentools en informatie','Berekeningen zijn scenario’s op basis van gebruikersinvoer. Ze zijn geen gegarandeerde waarde, financieel advies of technische keuring.')]),True)
 add('werken-bij','Werken bij VerkoopJouwBus','Informeer naar mogelijkheden om bij VerkoopJouwBus te werken.',paragraphs([('Interesse in bedrijfswagens?','Er is op deze website geen bevestigde openstaande vacature gepubliceerd. Wil je informeren naar mogelijkheden, mail dan info@verkoopjouwbus.nl met een korte introductie.'),('Deel alleen wat nodig is','Vraag eerst of en hoe een sollicitatie kan worden aangeleverd. Stuur geen identiteitsbewijs of gevoelige persoonsgegevens in een eerste bericht.')]))
 add('pers','Pers en data','Contact voor vragen over VerkoopJouwBus en de gebruikte informatiebronnen.',paragraphs([('Persvragen','Mail info@verkoopjouwbus.nl met je vraag en gewenste reactiedatum. Er zijn geen gecontroleerde bedrijfscijfers of onderzoeksrapporten gepubliceerd in deze versie.'),('Databronnen','De voertuigcheck gebruikt openbare RDW-data. Statistiekpagina’s verwijzen naar officiële bronnen en bevatten geen zelfbedachte totalen. Citeer een bron altijd met dataset, datum en methode.'),('Naam en merk','De naam van deze website is VerkoopJouwBus. De referentiewebsite AutoZoWeg is een ontwerpreferentie en geen onderdeel van deze dienst.')]))
 add('dealer-portal/registreren','Interesse als zakelijke koper','Meld interesse in contact met VerkoopJouwBus als zakelijke koper.','<p>Dit is een interesseformulier, geen actief dealeraccount of toegang tot een veiling. Aanmelding en afspraken worden afzonderlijk beoordeeld.</p><form name="dealer-interesse" method="POST" action="/bedankt/" data-netlify="true" netlify-honeypot="website"><input type="hidden" name="form-name" value="dealer-interesse"><label class="hidden">Niet invullen<input name="website"></label><div class="form-grid"><label class="wide">Bedrijfsnaam<input name="bedrijfsnaam" required maxlength="150" autocomplete="organization"></label><label>Contactpersoon<input name="contactpersoon" required maxlength="100" autocomplete="name"></label><label>E-mailadres<input name="email" type="email" required autocomplete="email"></label><label class="wide">Toelichting<textarea name="toelichting" rows="4" maxlength="2500"></textarea></label><label class="wide check"><input type="checkbox" required name="privacy-akkoord" value="ja"><span>Ik heb de <a href="/privacy/">privacy-informatie</a> gelezen en vraag contact aan.</span></label><button class="btn wide">Verstuur interesse</button></div></form>')
